import java.math.*;

public final class Loan {
    public static BigDecimal monthlyPayment(String principal, String annualRatePercent, int months) {
        if (months < 1) throw new IllegalArgumentException("months must be at least 1");
        MathContext mc = MathContext.DECIMAL64;
        BigDecimal p = new BigDecimal(principal);
        BigDecimal r = new BigDecimal(annualRatePercent).divide(BigDecimal.valueOf(1200), mc);
        if (r.signum() == 0) return p.divide(BigDecimal.valueOf(months), 2, RoundingMode.HALF_UP);
        BigDecimal growth = BigDecimal.ONE.add(r, mc).pow(months, mc);
        BigDecimal discount = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(growth, mc), mc);
        return p.multiply(r, mc).divide(discount, mc).setScale(2, RoundingMode.HALF_UP);
    }

    public static BigDecimal totalInterest(String principal, String annualRatePercent, int months) {
        return monthlyPayment(principal, annualRatePercent, months)
                .multiply(BigDecimal.valueOf(months))
                .subtract(new BigDecimal(principal))
                .setScale(2, RoundingMode.HALF_UP);
    }

    public static long checkedTotalCents(long[] amounts) {
        long total = 0;
        for (long a : amounts) total = Math.addExact(total, a);
        return total;
    }
}

unitTests:
test("a 12-month loan at 6%", () -> {
    checkEq(Loan.monthlyPayment("10000", "6", 12).toString(), "860.66");
    checkEq(Loan.totalInterest("10000", "6", 12).toString(), "327.92");
});

test("a mortgage-sized loan", () -> {
    checkEq(Loan.monthlyPayment("200000", "4.5", 360).toString(), "1013.37");
});

test("zero interest", () -> {
    checkEq(Loan.monthlyPayment("1200", "0", 12).toString(), "100.00");
    checkEq(Loan.totalInterest("1200", "0", 12).toString(), "0.00");
});

test("bad months", () -> {
    checkThrows(IllegalArgumentException.class, () -> Loan.monthlyPayment("100", "5", 0));
});

test("checked totals", () -> {
    checkEq(Loan.checkedTotalCents(new long[] {150, 250, 600}), 1000L);
    checkThrows(ArithmeticException.class, () -> Loan.checkedTotalCents(new long[] {Long.MAX_VALUE, 1}));
});

